mapper.select:
SELECT * FROM ( select '${PAGE_DATE_STATUS01}' statusValid, listagg(t8.CASH_TYPE, ',') within group ( order by t8.CASH_TYPE ) CASH_TYPE, t8.SEC_ACCT_ID secManageAcctId, CASE WHEN fp.FINPROD_NAME IS NOT NULL THEN 1 ELSE 0 end channel, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, t10.FINPROD_MARKET_ID, t10.FINPROD_ABBR finprodAbbr, to_char(min(t8.VDATE), 'yyyy-MM-dd') vDate, to_char(t8.MDATE, 'yyyy-MM-dd') mDate, t8.qty*100 qty, to_char(t8.PAY_DATE, 'yyyy-MM-dd') PAY_DATE, ROUND(SUM(t8.fpriceAmt), 2) fpriceAmt, T8.FINPROD_ID from ( select T6.FINPROD_ID, SUM(T6.AMOUNT) QTY,/*考虑投资目的数量合并*/ T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, SUM(T6.CASH_AMT * T6.AMOUNT) fpriceAmt,/*理论本息总额*/ case t6.CASH_TYPE when '${CASH_CLASS_TYPE01}' then 0 else ROUND(SUM(T6.PRIN_AMT * T6.AMOUNT), 2) end prinAmt,/*还本金额*/ T6.SEC_ACCT_ID, ROUND(SUM(t6.INT_AMT * T6.AMOUNT), 2) intAmt,/*理论利息*/ t6.PAY_DATE from ( select * from ( SELECT T1.FINPROD_ID, DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1, '11', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT, T1.SEC_ACCT_ID, t2.vdate, t2.mdate, t2.cash_amt, t2.prin_amt, t2.int_amt, t2.cash_id, t2.cash_type, t2.pay_date FROM PTL_SEC_POSITION_RULE T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T2.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND t1.CDATE < t2.MDATE LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T1.PORTFOLIO_ID
T1.AMOUNT > 0
AND T1.HODING_TYPE = 'A_004' and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and T2.CASH_TYPE IN (#{CASH_CLASS_TYPE01},#{CASH_CLASS_TYPE02},#{CASH_CLASS_TYPE03},#{CASH_CLASS_TYPE04}) and (t2.INT_AMT > 0 or t2.PRIN_AMT > 0) and t2.mdate = (select min(tt.mdate) from FIN_CASH_PLAN tt where tt.finprod_id =t1.finprod_id and Tt.FINPROD_TYPE2 = 'F01' AND tt.MDATE > t1.CDATE AND Tt.PAY_DATE >= #{PLATEFORM_DATE} and Tt.CASH_TYPE IN ('01', '02', '03', '04') and (tt.INT_AMT > 0 or t2.PRIN_AMT > 0) ) /*不存在生效的交易*/ and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA LEFT JOIN TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID where TDTA.MP_FINPROD_ID IS NULL AND TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.BUSI_TYPE = #{TRD10} AND TPDA.IS_CANCEL = #{YESNO_N} and T2.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND (TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID OR TPDA.CHL_ID = T1.SEC_ACCT_ID)) /*不存在流程中的当期或之前的交易*/ AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID where TDTA.MP_FINPROD_ID IS NULL AND TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.BUSI_TYPE = #{TRD10} AND TPDA.IS_CANCEL = #{YESNO_N} and T2.MDATE >= TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND (TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID OR TPDA.CHL_ID = T1.SEC_ACCT_ID))
AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION_RULE tpsp where tpsp.HODING_TYPE = T1.HODING_TYPE and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID and tpsp.FINPROD_ID = T1.FINPROD_ID and tpsp.CDATE > T1.CDATE and tpsp.CDATE < t2.MDATE ) and T2.PAY_DATE >= #{PLATEFORM_DATE}
) ) T6 GROUP BY T6.FINPROD_ID, T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, T6.PRIN_AMT,/*还本金额*/ T6.SEC_ACCT_ID, t6.INT_AMT, t6.PAY_DATE ) T8 LEFT JOIN FIN_PRODUCT T10 ON T10.FINPROD_ID = T8.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T8.SEC_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T8.SEC_ACCT_ID = FP.FINPROD_ID where t8.PAY_DATE = #{PLATEFORM_DATE} GROUP BY t8.SEC_ACCT_ID,SAI.SEC_ACCT_NAME, fp.FINPROD_NAME, t10.FINPROD_MARKET_ID, t10.FINPROD_ABBR, t8.MDATE, t8.qty, t8.PAY_DATE,T8.FINPROD_ID ORDER BY T8.MDATE )

SELECT
cash_id,
CASH_TYPE,
PORTFOLIO_ID,
PORTFOLIO_NAME,
INVEST_YESORNO,
FINPROD_ID,
CDATE,
SUM(AMOUNT) AMOUNT,
vDate,
mDate,
yield,
CALC_RULE
FROM (
SELECT
listagg(t5.CASH_TYPE, ',') within group ( order by t5.CASH_ID ) CASH_TYPE,
listagg(t5.CASH_ID, ',') within group ( order by t5.CASH_ID ) CASH_ID,
T1.PORTFOLIO_ID,
pp.PORTFOLIO_NAME,
pp.INVEST_YESORNO,
T1.FINPROD_ID,
T1.CDATE,
DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1,'11', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT,
'${vDate}' vDate,
'${mDate}' mDate,
'${yield}' yield,
/*现金流支付规则.支付频率 付息周期*/ T4.PAY_CYCLE CALC_RULE
/*检索对象 组合持仓*/ FROM PTL_SEC_POSITION_RULE T1
/*left join 标的类金融产品*/ LEFT JOIN FIN_PRODUCT T2
/*on 组合持仓.金融产品代码 = 标的类金融产品.金融产品代码*/ ON T1.FINPROD_ID = T2.FINPROD_ID
/*left join 现金流信息*/ LEFT JOIN FIN_CASH_INFO T3
/*on 标的类金融产品.金融产品代码 = 现金流信息.业务代码*/ ON T1.FINPROD_ID = T3.FINPROD_ID
/*and 现金流信息.现金流一级类型 = 数据字典缓存.现金流一级类型.利息*/ AND T3.CASH_TYPE_1 = #{CASH_TYPE_1_02}
/*and 现金流信息.现金流二级类型 = 数据字典缓存.现金流二级类型.利息*/ AND T3.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
/*left join 现金流支付规则*/ LEFT JOIN FIN_CASH_PAY_RULE T4
/*on 现金流信息.现金流代码 = 现金流支付规则.现金流代码*/ ON T3.CASH_ID = T4.CASH_ID
/*and 生效日期 小于等于 传参.调整后计算结束日*/ AND T4.EFF_DATE <= #{adjustMDate}
LEFT JOIN FIN_CASH_PLAN T5 ON T1.FINPROD_ID = T5.FINPROD_ID AND T5.MDATE = #{adjustMDate}
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T1.PORTFOLIO_ID
/*检索条件 金融产品代码 = 传参.金融产品代码*/ where T1.FINPROD_ID = #{finprodId}
/*and 持仓类型 = 数据字典缓存.持仓类型.实际*/

 AND T1.HODING_TYPE = 'A_004'
/*and 组合持仓.日期 = 平台日*/ AND t1.CDATE < #{adjustMDate}
AND T1.SEC_ACCT_ID = #{secAcctId}
and T1.AMOUNT > 0
AND nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
AND NOT EXISTS (
SELECT 1 FROM PTL_SEC_POSITION_RULE tpsp
where tpsp.HODING_TYPE = T1.HODING_TYPE
and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID
and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID
and tpsp.FINPROD_ID = T1.FINPROD_ID
and tpsp.CDATE > T1.CDATE
and tpsp.CDATE < #{adjustMDate}
)
/*不存在生效的交易*/
and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA
LEFT JOIN TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID
where TDTA.MP_FINPROD_ID IS NULL
AND TPDA.TRADE_STATUS = #{TRADE_STATUS01}
AND TPDA.BUSI_TYPE = #{TRD10}
AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') = TPDA.MDATE
AND TPDA.FINPROD_ID = T1.FINPROD_ID
AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND (TPDA.CHL_ID = T1.SEC_ACCT_ID OR TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID))
/*不存在流程中的当期或之前的交易*/
AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA
LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID
where TDTA.MP_FINPROD_ID IS NULL
AND TPDA.TRADE_STATUS = #{TRADE_STATUS01}
AND TPDA.BUSI_TYPE = #{TRD10}
AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') >= TPDA.MDATE
AND TPDA.FINPROD_ID = T1.FINPROD_ID
AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND (TPDA.CHL_ID = T1.SEC_ACCT_ID OR TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID))
group by
pp.PORTFOLIO_NAME,
T1.PORTFOLIO_ID,
T1.FINPROD_ID,
PP.INVEST_YESORNO,
T1.CDATE,
T1.AMOUNT,
T1.HODING_TYPE,
T4.PAY_CYCLE
)
group by cash_id,
CASH_TYPE,
PORTFOLIO_ID,
PORTFOLIO_NAME,
INVEST_YESORNO,
FINPROD_ID,
CDATE,
vDate,
mDate,
yield,
CALC_RULE
having SUM(AMOUNT) > 0

select

from REG_FIN_PRODUCT_DEAL_TOTAL T1
WHERE T1.PS = #{psT39}
AND T1.TRADE_DATE = #{PLATEFORM_DATE}
AND T1.TRADE_STATUS = #{TRADE_STATUS01}
AND T1.IS_CANCEL != #{YESNO_Y}
